export function evaluate({ inputs, time }) {
  const g = 9.8;
  const u = sdk.clamp(Number(inputs && inputs.launchSpeed != null ? inputs.launchSpeed : 3), 3, 5);
  const show = !(inputs && inputs.showArrows === 'off');
  const T = u / g;
  const tEnd = 2 * T;
  const t = sdk.clamp(Number(time) || 0, 0, tEnd);
  let v = u - g * t;
  if (Math.abs(v) < 1e-9) v = 0;
  const h = Math.max(0, u * t - g * t * t / 2);
  const a = -g;
  const H = u * u / (2 * g);
  let vTop = u - g * T;
  if (Math.abs(vTop) < 1e-9) vTop = 0;
  const released = t >= T - 1e-9;
  const dt = Math.max(0, t - T);
  const hh = released ? Math.max(0, H - g * dt * dt / 2) : H;
  let hv = released ? -g * dt : 0;
  if (Math.abs(hv) < 1e-9) hv = 0;
  const ha = released ? -g : 0;

  const Y0 = 470, PPM = 260;
  const Y = (m) => Y0 - PPM * m;
  const xT = 360, xH = 600;
  const VS = 14, AL = 50;
  const o = [];

  // height axis
  o.push(sdk.line('axis', 200, Y(0), 200, Y(1.35)));
  o.push(sdk.text('axisLabel', 200, Y(1.35) - 14, 'height (m), up +', { align: 'middle' }));
  [0, 0.5, 1].forEach((m, i) => {
    o.push(sdk.line('tick' + i, 192, Y(m), 208, Y(m)));
    o.push(sdk.text('tickL' + i, 178, Y(m) + 5, sdk.format(m, 1), { align: 'middle' }));
  });
  // launch mark
  o.push(sdk.line('launchMarkT', xT - 18, Y0 + 16, xT + 18, Y0 + 16, { opacity: 0.6 }));
  o.push(sdk.line('launchMarkH', xH - 18, Y0 + 16, xH + 18, Y0 + 16, { opacity: 0.6 }));
  o.push(sdk.text('launchLabel', (xT + xH) / 2, Y0 + 5, 'launch mark (h = 0)', { align: 'middle' }));
  // apex line with the values at the top
  o.push(sdk.line('apexLine', 220, Y(H), 680, Y(H), { opacity: 0.35, role: 'prediction' }));
  o.push(sdk.text('apexLabel', 720, Y(H) - 10, 'top ' + sdk.format(H, 3) + ' m', { role: 'prediction' }));
  o.push(sdk.text('apexValues', 720, Y(H) + 10, 'v = ' + sdk.format(vTop, 0) + ', a = ' + sdk.format(a, 1) + ' m/s^2', { role: 'prediction' }));

  // column titles
  o.push(sdk.text('tossedTitle', xT, 60, 'Tossed ball', { align: 'middle' }));
  o.push(sdk.text('heldTitle', xH, 60, 'Held ball', { align: 'middle' }));

  // gate
  const gy = Y(H) + 15;
  if (!released) {
    o.push(sdk.box('gateL', xH - 22, gy, 22, 6, { role: 'neutral' }));
    o.push(sdk.box('gateR', xH, gy, 22, 6, { role: 'neutral' }));
    o.push(sdk.text('gateLabel', 660, gy + 24, 'gate closed'));
  } else {
    o.push(sdk.box('gateL', xH - 100, gy, 22, 6, { role: 'neutral' }));
    o.push(sdk.box('gateR', xH + 78, gy, 22, 6, { role: 'neutral' }));
    o.push(sdk.text('gateLabel', 660, gy + 24, 'gate open'));
  }

  // balls
  const yT = Y(h), yH = Y(hh);
  o.push(sdk.circle('tossedBall', xT, yT, 28, { role: 'input' }));
  o.push(sdk.circle('heldBall', xH, yH, 28, { role: 'learner' }));

  function arrows(p, x, y, vel, acc) {
    if (Math.abs(vel) < 0.05) {
      o.push(sdk.circle(p + 'vDot', x + 24, y, 8, { role: 'output' }));
      o.push(sdk.text(p + 'vL', x + 34, y - 22, 'v = 0', { role: 'output' }));
    } else {
      const y2 = y - vel * VS;
      o.push(sdk.arrow(p + 'vArrow', x + 24, y, x + 24, y2, { role: 'output' }));
      o.push(sdk.text(p + 'vL', x + 34, (y + y2) / 2 + 5, 'v', { role: 'output' }));
    }
    if (acc !== 0) {
      o.push(sdk.arrow(p + 'aArrow', x - 24, y, x - 24, y + AL, { role: 'warning' }));
      o.push(sdk.text(p + 'aL', x - 38, y + AL / 2 + 5, 'a', { role: 'warning', align: 'middle' }));
    } else {
      o.push(sdk.text(p + 'aL', x - 40, y - 22, 'a = 0', { role: 'warning', align: 'middle' }));
    }
  }
  if (show) {
    arrows('t', xT, yT, v, a);
    arrows('h', xH, yH, hv, ha);
  }

  // in-scene readouts
  const fx = 930;
  const sgn = (x, d) => (x > 0 ? '+' : '') + sdk.format(x, d);
  o.push(sdk.text('rTitle', fx, 130, 'Tossed ball'));
  o.push(sdk.text('rH', fx, 158, 'h = ' + sdk.format(h, 3) + ' m'));
  o.push(sdk.text('rV', fx, 184, 'v = ' + sgn(v, 2) + ' m/s', { role: 'output' }));
  o.push(sdk.text('rA', fx, 210, 'a = ' + sdk.format(a, 1) + ' m/s^2', { role: 'warning' }));
  o.push(sdk.text('rHeldTitle', fx, 260, 'Held ball'));
  o.push(sdk.text('rHV', fx, 288, 'v = ' + sgn(hv, 2) + ' m/s', { role: 'output' }));
  o.push(sdk.text('rHA', fx, 314, released ? 'a = ' + sdk.format(ha, 1) + ' m/s^2' : 'a = 0 (held by gate)', { role: 'warning' }));

  return {
    frame: {
      width: 1120, height: 590, objects: o,
      readouts: [
        { id: 'tossedHeight', value: h },
        { id: 'tossedVelocity', value: v },
        { id: 'tossedAcceleration', value: a }
      ]
    },
    quantities: { launchSpeed: u, gravity: g, velocity: v, acceleration: a, apexTime: T, height: h }
  };
}
